from itertools import combinations
S={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
# placements square and 4 L triomino orientations
shapes=[]
for name, cells in [('1',[(0,0),(0,1),(1,0),(1,1)]),('2',[(0,1),(1,0),(1,1)]),('3',[(0,0),(0,1),(1,1)]),('4',[(0,0),(1,0),(1,1)]),('5',[(0,0),(0,1),(1,0)])]:
    shapes.append((name,cells))
placements=[]
for name,shape in shapes:
  for r in range(4):
    for c in range(6):
      p=frozenset((r+dr,c+dc) for dr,dc in shape)
      if p<=S: placements.append((name,p))
sol=[]
def rec(rem,cur):
  if not rem:
    sol.append(cur[:]); return
  x=min(rem)
  for name,p in placements:
    if x in p and p<=rem:
      rec(rem-p,cur+[(name,p)])
rec(S,[])
print('solutions',len(sol))
for s in sol[:20]:
 print([(n,sorted(p)) for n,p in s])

